CREATE OR REPLACE VIEW cu_jhallrobinson.V_EMPLOYEE ( EMPLOYEE_GUID, FIRST_NAME, EMAIL, PHONE_NUMBER, HIRE_DATE ) AS
select e.employee_guid, e.first_name, e.email, e.phone_number, min(ep.effective_date) hire_date
from employees e
inner join employment em
on e.employee_guid = em.employee_guid
inner join employment_pay ep
on em.employment_guid = ep.employment_guid
group by  e.employee_guid, e.first_name, e.email, e.phone_number 
;

CREATE OR REPLACE VIEW cu_jhallrobinson.V_EMPLOYMENT ( EMPLOYEE_GUID, EMPLOYMENT_GUID, FIRST_NAME, EMAIL, PHONE_NUMBER, START_DATE, END_DATE, SALARY, COMMISSION_PCT ) AS
SELECT
    e.employee_guid,
    em.employment_guid,
    e.first_name,
    e.email,
    e.phone_number,
    ep.effective_date start_date,
    LEAD(ep.effective_date, 1)
    OVER(PARTITION BY e.employee_guid
         ORDER BY
             ep.effective_date
    ) -1                AS end_date,
    ep.salary,
    ep.commission_pct
FROM
         employees e
    INNER JOIN employment     em ON e.employee_guid = em.employee_guid
    INNER JOIN employment_pay ep ON em.employment_guid = ep.employment_guid 
;

